import { Stack } from "@/shared/ui/layout/Stack";
import { Row } from "@/shared/ui/layout/Row";
import { Spacer } from "@/shared/ui/layout/Spacer";
import { Text } from "@/shared/ui/typography/Text";
import { Box } from "@/shared/ui/layout/Box";
import { StatusDot } from "@/shared/ui/feedback/StatusDot";
import { IssueCard } from "@/features/planner/github/IssueCard";

interface BoardColumn { id: string; name: string; color: string }
interface BoardIssue {
  id: string; number: number; title: string; body: string; state: "OPEN" | "CLOSED";
  labels: { name: string; color: string }[];
  assignees: { login: string }[];
  comments: number;
  milestone: string | null;
  focused?: boolean;
}
const DEFAULT_COL: BoardColumn = { id: "c1", name: "In progress", color: "var(--accent)" };
const DEFAULT_ISSUES: BoardIssue[] = [
  { id: "1", number: 142, title: "Fix flaky retry logic in the sync worker", body: "", state: "OPEN", labels: [{ name: "bug", color: "d73a4a" }], assignees: [{ login: "kevin" }], comments: 3, milestone: "v1.2" },
  { id: "2", number: 156, title: "Add pagination to the issues list", body: "", state: "OPEN", labels: [], assignees: [], comments: 0, milestone: null },
];
export function Column({
  col = DEFAULT_COL, issues = DEFAULT_ISSUES, onIssueClick = () => {},
}: { col?: BoardColumn; issues?: BoardIssue[]; onIssueClick?: (n: number) => void }) {
  return (
    <Stack style={{
      flex: "1 1 0", minWidth: 230,
      background: "var(--bg-panel)",
      borderRadius: 8, border: "1px solid var(--border-soft)", overflow: "hidden",
    }}>
      <Row className="mono" gap={8} style={{
        padding: "10px 12px", borderBottom: "1px solid var(--border-soft)",
        background: "var(--bg-elev)",
        fontSize: 11,
      }}>
        <StatusDot color={col.color} size={7} />
        <Text as="span" style={{ color: "var(--fg)" }}>{col.name}</Text>
        <Text tone="dim">{issues.length}</Text>
        <Spacer />
        <Text tone="dim" style={{ cursor: "pointer" }}>+</Text>
        <Text tone="dim" style={{ cursor: "pointer" }}>⋯</Text>
      </Row>
      <Stack gap={7} style={{ flex: 1, overflow: "auto", padding: 8 }}>
        {issues.map(c => (
          <IssueCard key={c.id} issue={c} focused={c.focused} onClick={() => onIssueClick(c.number)} />
        ))}
        <Box pad={[7, 9]} radius={5} style={{
          marginTop: 4,
          border: "1px dashed var(--border)",
          textAlign: "center", fontSize: 10, color: "var(--fg-dim)", cursor: "pointer",
        }} className="mono">+ new card</Box>
      </Stack>
    </Stack>
  );
}
